const input = $input.first().json || {};

const userPrompt = (input.userPrompt || '').toString().trim();
if (!userPrompt) {
  throw new Error('AUTO-COM-001: userPrompt is required but was empty or missing. Caller must pass a non-empty userPrompt.');
}

const systemPromptCaller = (input.systemPrompt || '').toString();
// 共通ガードレール（[仮定/推奨]：全呼び出し元に一律で軽量な事実確認ガードレールを付与する設計判断。
// 案件固有のハルシネーション防止指示は呼び出し元のsystemPromptで別途付与すること）
const commonGuardrail = '\n\n[共通ガードレール]事実と推測を明確に分けて記述してください。確認できない情報は断定せず、不確実である旨を明記してください。実在しない法令・制度・統計・実績・固有名詞を作成しないでください。';
const systemPrompt = (systemPromptCaller + commonGuardrail).trim();

const model = (input.model || 'claude-sonnet-5').toString();
const maxTokens = Number.isFinite(input.maxTokens) ? input.maxTokens : 4000;
const temperature = Number.isFinite(input.temperature) ? input.temperature : 1;

// --- 2026-09-27追加：outputSchema（任意）の検証 ---
// 新規呼び出し元（AUTO-SLK-001/002等）が明示的に渡した場合のみこの分岐へ入る。
// 既存呼び出し元はこのキー自体を渡さないため outputSchema === undefined となり、以下は素通りする。
const outputSchema = input.outputSchema;
if (outputSchema !== undefined && outputSchema !== null) {
  if (typeof outputSchema !== 'object' || Array.isArray(outputSchema)) {
    throw new Error('AUTO-COM-001: outputSchema must be a JSON object when provided (received ' + (Array.isArray(outputSchema) ? 'array' : typeof outputSchema) + ').');
  }
}

return [{
  json: {
    systemPrompt,
    userPrompt,
    model,
    maxTokens,
    temperature,
    ...(outputSchema !== undefined && outputSchema !== null ? { outputSchema } : {})
  }
}];

const d = $input.first().json;

const body = {
  model: d.model,
  max_tokens: d.maxTokens,
  temperature: d.temperature,
  messages: [
    { role: 'user', content: d.userPrompt }
  ]
};
if (d.systemPrompt) {
  body.system = d.systemPrompt;
}
if (d.outputSchema) {
  body.output_config = { format: { type: 'json_schema', schema: d.outputSchema } };
}

return [{ json: body }];

const resp = $input.first().json;
const textBlock = (resp.content || []).find(b => b.type === 'text');
const text = (textBlock && textBlock.text) || '';

const result = {
  success: true,
  text,
  model: resp.model || null,
  stopReason: resp.stop_reason || null,
  usage: resp.usage || null
};

const validated = $('入力検証・デフォルト適用').first().json;
if (validated && validated.outputSchema) {
  try {
    result.parsed = JSON.parse(text);
  } catch (e) {
    // パース失敗時はparsedを付けないだけ。throwしない（呼び出し元のIF分岐に委ねる）。
  }
}

return [{ json: result }];

const err = $input.first().json.error || {};
const detail = typeof err === 'string' ? err : JSON.stringify(err);
throw new Error('AUTO-COM-001: Claude API call failed after retries. detail=' + detail);
